import { Table, GenericColumn, StringColumn, BooleanColumn } from '@servicenow/sdk/core'

export const sys_email_layout = Table({
    allowWebServiceAccess: true,
    audit: true,
    display: 'name',
    extends: 'sys_metadata',
    label: 'Email Layout',
    name: 'sys_email_layout',
    schema: {
        layout: GenericColumn({
            columnType: 'html',
            label: 'Layout',
            maxLength: 65536,
        }),
        sys_id: GenericColumn({
            columnType: 'GUID',
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
        name: StringColumn({
            label: 'Name',
            maxLength: 100,
        }),
        advanced: BooleanColumn({
            default: false,
            label: 'Advanced',
        }),
        advanced_layout: GenericColumn({
            columnType: 'xml',
            label: [
                {
                    hint: 'Must be in XML format',
                    label: 'Advanced Layout',
                    plural: 'Advanced Layouts',
                    language: 'en',
                },
            ],
            maxLength: 65000,
            xmlView: true,
        }),
        description: StringColumn({
            label: 'Description',
            maxLength: 1000,
        }),
    },
    textIndex: true,
})
